package bytecode

import (
	"archive/tar"
	"compress/gzip"
	"io"
	"os"
	"strconv"
	"strings"
	"testing"
)

// All expected rows are retained native libbz2 output, not generated by the
// Go decoder. Every call compares consumed bytes, output, status and output
// bytes, including malformed RLE output publication and trailing streams.
func TestBzip2StreamReferenceReplay(t *testing.T) {
	file, err := os.Open("testdata/bzip2_stream_reference.tar.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	z, err := gzip.NewReader(file)
	if err != nil {
		t.Fatal(err)
	}
	defer z.Close()
	tarReader := tar.NewReader(z)
	corpus := map[string][]byte{}
	traces, calls := 0, 0
	for {
		header, err := tarReader.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
		if header.Typeflag != tar.TypeReg || header.Size < 0 || header.Size > 8<<20 {
			t.Fatal("invalid reference archive member")
		}
		if name, ok := strings.CutPrefix(header.Name, "corpus/"); ok {
			if _, exists := corpus[name]; exists {
				t.Fatal("duplicate input")
			}
			data, err := io.ReadAll(tarReader)
			if err != nil {
				t.Fatal(err)
			}
			corpus[name] = data
			continue
		}
		name, ok := strings.CutPrefix(header.Name, "traces/")
		if !ok {
			t.Fatalf("unknown member %s", header.Name)
		}
		parts := strings.Split(strings.TrimSuffix(name, ".txt.gz"), "-")
		if len(parts) < 3 {
			t.Fatal("invalid trace name")
		}
		inWindow, e1 := strconv.Atoi(parts[len(parts)-2])
		outWindow, e2 := strconv.Atoi(parts[len(parts)-1])
		if e1 != nil || e2 != nil || inWindow < 1 || outWindow < 1 || inWindow > 1<<20 || outWindow > 1<<20 {
			t.Fatal("invalid window")
		}
		packed, ok := corpus[strings.Join(parts[:len(parts)-2], "-")]
		if !ok {
			t.Fatal("missing trace input")
		}
		trace, err := gzip.NewReader(tarReader)
		if err != nil {
			t.Fatal(err)
		}
		t.Run(name, func(t *testing.T) { calls += compareBzip2Trace(t, packed, inWindow, outWindow, trace) })
		if err := trace.Close(); err != nil {
			t.Fatal(err)
		}
		traces++
	}
	if len(corpus) != 265 || traces != 1855 || calls != 1809696 {
		t.Fatalf("reference inventory: inputs=%d traces=%d calls=%d", len(corpus), traces, calls)
	}
	t.Logf("replayed %d independent libbz2 calls across %d traces", calls, traces)
}
